00070 Surface InverseTransformDDS::process(int width, int height, const Surface src_layers[]) {
00071     const SurfaceView<int16_t> coeffs[16] = {
00072         SurfaceView<int16_t>(src_layers[0]),  SurfaceView<int16_t>(src_layers[1]),  SurfaceView<int16_t>(src_layers[2]),
00073         SurfaceView<int16_t>(src_layers[3]),  SurfaceView<int16_t>(src_layers[4]),  SurfaceView<int16_t>(src_layers[5]),
00074         SurfaceView<int16_t>(src_layers[6]),  SurfaceView<int16_t>(src_layers[7]),  SurfaceView<int16_t>(src_layers[8]),
00075         SurfaceView<int16_t>(src_layers[9]),  SurfaceView<int16_t>(src_layers[10]), SurfaceView<int16_t>(src_layers[11]),
00076         SurfaceView<int16_t>(src_layers[12]), SurfaceView<int16_t>(src_layers[13]), SurfaceView<int16_t>(src_layers[14]),
00077         SurfaceView<int16_t>(src_layers[15])};
00078 
00079     auto dst = Surface::build_from<int16_t>();
00080     dst.reserve(width, height);
00081 #if defined __OPT_MATRIX__
00082     for (unsigned y = 0; y < static_cast<unsigned>(height) / 4; y++) {
00083         unsigned dy = y * 4;
