00101         int16_t *pd01 = dst.data(0, dy + 1);
00102         int16_t *pd02 = dst.data(0, dy + 2);
00103         int16_t *pd03 = dst.data(0, dy + 3);
00104         for (unsigned x = 0; x < static_cast<unsigned>(width) / 4; x++) {
00105             // unsigned dx = x * 4;
00106             int16_t c00 = *pc00++;
00107             int16_t c01 = *pc01++;
00108             int16_t c02 = *pc02++;
00109             int16_t c03 = *pc03++;
00110             int16_t c04 = *pc04++;
00111             int16_t c05 = *pc05++;
00112             int16_t c06 = *pc06++;
