00122 
00123             *pd00++ = c00 + c01 + c02 + c03 + c04 + c05 + c06 + c07 + c08 + c09 + c10 + c11 + c12 + c13 + c14 + c15;
00124             *pd00++ = c00 + c01 + c02 + c03 - c04 - c05 - c06 - c07 + c08 + c09 + c10 + c11 - c12 - c13 - c14 - c15;
